    "5": ["reduced", "Reduced detail", "Requested 5 m, but available imagery is approximately 10 m."],
    "10": ["compatible", "Compatible", "Requested 10 m. Selected imagery supports approximately 10 m."],
    "20": ["compatible", "Compatible", "Requested 20 m. Selected imagery supports approximately 10 m; output may be resampled."],
    "30": ["compatible", "Compatible", "Requested 30 m. Selected imagery supports approximately 10 m; output may be resampled."],
