if(firstSample){el("home-image").src=firstSample[1].views.optical;el("home-image-caption").textContent="Sample "+firstSample[0]+" · "+firstSample[1].crs+" · "+firstSample[1].shape.join(" × ")+" pixels · RGB display";}
